	node1a := &k8sv1.Node{
		ObjectMeta: metav1.ObjectMeta{
			Name:        "node1a",
			Annotations: map[string]string{},
		},
	}
	node1b := &k8sv1.Node{
		ObjectMeta: metav1.ObjectMeta{
			Name:        "node1b",
			Annotations: map[string]string{},
		},
	}
	Expect(k8sClient.Create(ctx, node1a)).To(Succeed())
	Expect(k8sClient.Create(ctx, node1b)).To(Succeed())

	node2a := &k8sv1.Node{
		ObjectMeta: metav1.ObjectMeta{
			Name:        "node2a",
			Annotations: map[string]string{},
		},
	}
	node2b := &k8sv1.Node{
		ObjectMeta: metav1.ObjectMeta{
			Name:        "node2b",
			Annotations: map[string]string{},
		},
	}
	Expect(k8sClient.Create(ctx, node2a)).To(Succeed())
	Expect(k8sClient.Create(ctx, node2b)).To(Succeed())

	node3a := &k8sv1.Node{
		ObjectMeta: metav1.ObjectMeta{
			Name:        "node3a",
			Annotations: map[string]string{},
		},
	}
	Expect(k8sClient.Create(ctx, node3a)).To(Succeed())

	ns := k8sv1.Namespace{
		ObjectMeta: metav1.ObjectMeta{
			Name: "namespace",
		},
	}
	Expect(k8sClient.Create(ctx, &ns)).To(Succeed())
}

var _ = AfterSuite(func() {
	cancel()
	By("tearing down the test environment")
	err := testEnv.Stop()
	Expect(err).NotTo(HaveOccurred())
})

